    and.b32 %r31, %r30, 31;       // lane id
    shr.u32 %r32, %r30, 5;        // warp id
    mov.b32 %r33, %f2;
    shfl.sync.down.b32 %r34, %r33, 16, 31, 0xffffffff;
    mov.b32 %f41, %r34;
    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f2;
    shfl.sync.down.b32 %r34, %r33, 8, 31, 0xffffffff;
    mov.b32 %f41, %r34;
    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f2;
    shfl.sync.down.b32 %r34, %r33, 4, 31, 0xffffffff;
    mov.b32 %f41, %r34;
    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f2;
    shfl.sync.down.b32 %r34, %r33, 2, 31, 0xffffffff;
    mov.b32 %f41, %r34;
    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f2;
    shfl.sync.down.b32 %r34, %r33, 1, 31, 0xffffffff;
    mov.b32 %f41, %r34;
    add.f32 %f2, %f2, %f41;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 16, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 8, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 4, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 2, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    mov.b32 %r33, %f3;
    shfl.sync.down.b32 %r34, %r33, 1, 31, 0xffffffff;
    mov.b32 %f42, %r34;
    add.f32 %f3, %f3, %f42;
    // Each warp's lane 0 now holds the warp partial sums.
    setp.ne.u32 %p8, %r31, 0;
    @%p8 bra SKIP_WARP_STORE;
    mul.wide.u32 %rd53, %r32, 4;
    mov.u64 %rd54, s_sum;
    add.u64 %rd55, %rd54, %rd53;
    st.shared.f32 [%rd55], %f2;
    mov.u64 %rd56, s_sq;
    add.u64 %rd57, %rd56, %rd53;
    st.shared.f32 [%rd57], %f3;
SKIP_WARP_STORE:
    bar.sync 0;
    // Thread 0 reduces the (blockDim.x/32) warp partials sequentially.
    setp.ne.u32 %p9, %r3, 0;
    @%p9 bra SKIP_FINAL_REDUCE;
    mov.f32 %f43, 0f00000000;
    mov.f32 %f44, 0f00000000;
    mov.u32 %r36, 0;
    shr.u32 %r37, %r4, 5;         // numWarps = blockDim.x / 32
